class EnvVarCheck
{
    /// <summary>
    /// Checks whether an environment variable is truly set (even if empty),
    /// working around the .NET 9 behavioral change where empty vars return null.
    /// </summary>
    private static bool IsEnvironmentVariableSet(string variable)
    {
        // Check /proc/self/environ on Linux to distinguish "not set" from "set to empty"
        if (OperatingSystem.IsLinux())
        {
            var environ = File.ReadAllText("/proc/self/environ");
            return environ.Split('\0').Any(e => e == variable + "=" || e.StartsWith(variable + "="));
        }
        return Environment.GetEnvironmentVariable(variable) != null;
    }

    void CheckFlag()
    {

